      "rationale": "Contrast ratios are verified by using automated accessibility tools to calculate the contrast between text and background colors."
    },
    {
      "requirement_id": "KDH-066",
      "methods": [
        "Test"
      ],
      "rationale": "Text resizing is verified by zooming the browser to 200% and checking for content loss or functional impairment."
    },
    {
      "requirement_id": "KDH-067",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Use of text instead of images is verified by inspecting the HTML source to ensure information is conveyed via text elements where possible."
    },
    {
      "requirement_id": "KDH-068",
      "methods": [
        "Test"
      ],
      "rationale": "Spacing adjustments are verified by applying CSS overrides for line height, paragraph spacing, and letter spacing to check for layout breakage."
    },
    {
      "requirement_id": "KDH-069",
      "methods": [
        "Test"
      ],
      "rationale": "Keyboard accessibility is verified by navigating and interacting with all portal functions using only the keyboard without time constraints."
    },
    {
      "requirement_id": "KDH-070",
      "methods": [
        "Test"
      ],
      "rationale": "Session timeout warning is verified by waiting 25 minutes of inactivity to observe the dialog, screen reader announcement, and extension functionality."
    },
    {
      "requirement_id": "KDH-071",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Page titles are verified by inspecting the HTML source to ensure each page has a descriptive <title> element."
    },
    {
      "requirement_id": "KDH-072",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Link purpose clarity is verified by inspecting the HTML source to ensure link text or aria-labels clearly describe the destination."
    },
    {
      "requirement_id": "KDH-073",
      "methods": [
        "Test"
      ],
      "rationale": "Focus visibility is verified by navigating with the keyboard and observing that a visible focus indicator appears on all interactive elements."
    },
    {
      "requirement_id": "KDH-074",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Language declaration is verified by inspecting the HTML source to ensure the <html> tag has the correct lang attribute."
    },
    {
      "requirement_id": "KDH-075",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Language of sections is verified by inspecting the HTML source to ensure lang attributes are applied to elements containing text in a different language."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KDH-101",
      "methods": [
        "Test"
      ],
      "rationale": "Hareketsizlik kilidi ve FIDO2/PIN ile yeniden kimlik doğrulama akışının, sistem çalıştırılarak ve girdi verilerek gözlemlenmesi gerekir."
    },
    {
      "requirement_id": "KDH-102",
      "methods": [
        "Test"
      ],
      "rationale": "Oturumun belirlenen koşullarda otomatik sonlandırılmasının, sistem üzerinde süre ve koşul manipülasyonu yapılarak doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-103",
      "methods": [
        "Test"
      ],
      "rationale": "Denetim kayıtlarının gerekli alanları (tür, zaman, yer, kaynak, sonuç, kimlik) içerip içermediğinin, olaylar üretilip loglar incelenerek doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-104",
      "methods": [
        "Test"
      ],
      "rationale": "Zaman damgalarının UTC cinsinden ve iç sistem saatinden üretildiğinin, log kayıtları üzerinden gözlemlenerek doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-105",
      "methods": [
        "Test"
      ],
      "rationale": "Yetkisiz erişim, değişiklik veya silme denemelerinin algılanıp alarm üretildiğinin, sistem üzerinde saldırı simülasyonu yapılarak doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-106",
      "methods": [
        "Test"
      ],
      "rationale": "Parola ve OTP girdilerinin ekranda gizlendiğinin, kullanıcı arayüzünde girdi vererek ve ekran görüntüsü alarak doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-107",
      "methods": [
        "Test"
      ],
      "rationale": "Hassas işlemler öncesi tazelik süresi dolunca yeniden kimlik doğrulama zorunluluğunun, oturum süresi manipüle edilerek doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-108",
      "methods": [
        "Test"
      ],
      "rationale": "Veri iletiminin şifreli ve bütünlüklü olduğunun, ağ trafiği yakalanarak ve şifreleme protokolleri gözlemlenerek doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-109",
      "methods": [
        "Test"
      ],
      "rationale": "Geçersiz girdilerin reddedildiğinin, çeşitli hatalı ve aşırı girdilerle sistem çalıştırılarak doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-110",
      "methods": [
        "Test"
      ],
      "rationale": "Hata mesajlarının kullanıcıya genel bilgi verip detaylı bilginin sadece yetkili loglara yazıldığının, hata senaryoları üretilerek doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-111",
      "methods": [
        "Test"
      ],
      "rationale": "Oturum sonu uyarısı, taslak kaydı ve kaldığı yerden devam etme işlevinin, oturum süresi doldurulup işlem yapılarak doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-112",
      "methods": [
        "Test"
      ],
      "rationale": "CAPTCHA kullanılmadığının ve bot eşiği aşıldığında etkileşimsiz kanıt veya nesne tanıma sorgusunun gösterildiğinin, bot simülasyonu yapılarak doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-113",
      "methods": [
        "Test"
      ],
      "rationale": "Ödeme sonucunun imza doğrulaması, belirsiz durum yönetimi ve sorgulama aralığının, KÖA entegrasyonu simüle edilerek doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-114",
      "methods": [
        "Test"
      ],
      "rationale": "AAL2 altı veya eksik alanlı e-Devlet belirtecinin sınırlı kipte oturum açtığının, farklı AAL düzeylerinde giriş yapılarak doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-115",
      "methods": [
        "Test"
      ],
      "rationale": "Parola geçerlilik süresinin sadece şirket temsilcilerine uygulandığının, bildirimlerin ve zorunlu değişikliklerin, süre manipülasyonu ve sızıntı simülasyonu ile doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-116",
      "methods": [
        "Test"
      ],
      "rationale": "TOTP adım penceresi ve tek kullanımlık kuralının, farklı zaman damgaları ve tekrarlanan kodlarla doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-117",
      "methods": [
        "Test"
      ],
      "rationale": "Başarısız deneme eşiğinin doğrulayıcıyı devre dışı bıraktığının ve hesap kurtarma akışının, ardışık hatalı girişlerle doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-118",
      "methods": [
        "Test"
      ],
      "rationale": "AAL2 ve AAL3 oturumlarında hareketsizlik sonrası farklı yeniden kimlik doğrulama akışlarının ve oturum sırrı silinmesinin, oturum senaryolarıyla doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-119",
      "methods": [
        "Test"
      ],
      "rationale": "Eşzamanlı oturum sınırının aşıldığında en eski oturumun kapatılıp bildiriminin ve SIEM kaydının, çoklu oturum açılarak doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-120",
      "methods": [
        "Test"
      ],
      "rationale": "Dosya türü, içerik imzası ve boyut sınırlarının uygulandığının, çeşitli dosyalar yükleyip ret mesajlarını gözlemleyerek doğrulanması gerekir."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "ETC-051",
      "methods": [
