{
  "decisions": [
    {
      "requirement_id": "KDH-001",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement mandates the availability of specific authentication options, which is verified by executing the login flow and observing the presented choices."
    },
    {
      "requirement_id": "KDH-002",
      "methods": [
        "Test"
      ],
      "rationale": "The system's ability to enforce multi-factor or two-factor authentication at AAL2 is verified by attempting logins with valid and invalid factor combinations."
    },
    {
      "requirement_id": "KDH-003",
      "methods": [
        "Test"
      ],
      "rationale": "Periodic reauthentication behavior based on inactivity and overall timeouts is verified by simulating user sessions and observing session termination or re-prompting."
    },
    {
      "requirement_id": "KDH-004",
      "methods": [
        "Test"
      ],
      "rationale": "The sending of notifications upon account recovery is verified by triggering a recovery event and observing the delivery of the notification."
    },
    {
      "requirement_id": "KDH-005",
      "methods": [
        "Test"
      ],
      "rationale": "The distribution of notifications to registered addresses (excluding postal) is verified by triggering a notification event and checking the delivery logs or inboxes."
    },
    {
      "requirement_id": "KDH-006",
      "methods": [
        "Test"
      ],
      "rationale": "The decoupling of the e-Devlet assertion validity from the VBP session duration is verified by initiating a session and observing that the VBP session persists beyond the assertion's validity window."
    },
    {
      "requirement_id": "KDH-007",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The content of the federation assertion request, specifically the inclusion of the VBP identifier and cryptographic nonce, is verified by inspecting the network traffic or code implementation."
    },
    {
      "requirement_id": "KDH-008",
      "methods": [
        "Test"
      ],
      "rationale": "The validation of the assertion audience is verified by attempting to inject an assertion intended for a different relying party and observing its rejection."
    },
    {
      "requirement_id": "KDH-009",
      "methods": [
        "Test"
      ],
      "rationale": "The enforcement of the binding process for changing SMS phone numbers is verified by attempting to change the number and observing the required authentication steps."
    },
    {
      "requirement_id": "KDH-010",
      "methods": [
        "Test"
      ],
      "rationale": "The ability to bind multiple authenticators is verified by adding several authenticators to a single account and confirming their co-existence."
    },
    {
      "requirement_id": "KDH-011",
      "methods": [
        "Test"
      ],
      "rationale": "The authentication level required for binding a new authenticator is verified by attempting to bind an authenticator at different AAL levels and observing the system's response."
    },
    {
      "requirement_id": "KDH-012",
      "methods": [
        "Test"
      ],
      "rationale": "The sending of independent notifications upon adding an authenticator is verified by adding a new authenticator and observing the notification delivery via a separate channel."
    },
    {
      "requirement_id": "KDH-013",
      "methods": [
        "Test"
      ],
      "rationale": "The invalidation of confirmation codes after use is verified by using a code successfully and then attempting to reuse it, expecting rejection."
    },
    {
      "requirement_id": "KDH-014",
      "methods": [
        "Test"
      ],
      "rationale": "The validation of assertion signatures is verified by presenting an assertion with an invalid or tampered signature and observing its rejection."
    },
    {
      "requirement_id": "KDH-015",
      "methods": [
        "Test"
      ],
      "rationale": "Replay protection is verified by submitting the same valid assertion twice and observing that the second submission is rejected."
    },
    {
      "requirement_id": "KDH-016",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The initiation of federation transactions by VBP as the RP is verified by inspecting the sequence of network requests or the code logic governing the federation flow."
    },
    {
      "requirement_id": "KDH-017",
      "methods": [
        "Test"
      ],
      "rationale": "The prevention of information leakage during proofing is verified by submitting mismatched self-asserted information and observing that the error message does not reveal which specific attribute failed."
    },
    {
      "requirement_id": "KDH-018",
      "methods": [
