{
  "test_cases": [
    {
      "id": "TC-1",
      "title": "Setting a new phone number triggers authenticator binding process",
      "covers": [
        "KDH-009"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "A company representative account exists with a pre-registered telephone number. The user is authenticated.",
      "test_inputs": "A new valid telephone number.",
      "assumptions": "The system implements the NIST SP 800-63B-4 §4.1.2 binding process, which typically involves sending a one-time code to the new number and verifying it.",
      "steps": [
        {
          "no": 1,
          "action": "Navigate to the profile settings and select the option to change the pre-registered telephone number.",
          "expected": "The system initiates the authenticator binding process (e.g., prompts for a new number and sends a verification code to the new number) rather than simply saving the number."
        },
        {
          "no": 2,
          "action": "Enter the new telephone number and submit the request.",
          "expected": "The system sends a one-time code to the new telephone number and waits for verification."
        },
        {
          "no": 3,
          "action": "Enter the correct one-time code received on the new telephone number.",
          "expected": "The system verifies the code, completes the binding process, and updates the pre-registered telephone number to the new one."
        }
      ]
    },
    {
      "id": "TC-2",
      "title": "Changing phone number without verification fails",
      "covers": [
        "KDH-009"
      ],
      "type": "Hata",
      "priority": "Yüksek",
      "preconditions": "A company representative account exists with a pre-registered telephone number. The user is authenticated.",
      "test_inputs": "A new valid telephone number, an incorrect one-time code.",
      "assumptions": "The binding process requires successful verification of a code sent to the new number.",
      "steps": [
        {
          "no": 1,
          "action": "Initiate the change of the pre-registered telephone number to a new number.",
          "expected": "The system sends a one-time code to the new number."
        },
        {
          "no": 2,
          "action": "Enter an incorrect one-time code.",
          "expected": "The system rejects the code, displays an error message, and does not update the pre-registered telephone number."
        },
        {
          "no": 3,
          "action": "Check the current pre-registered telephone number in the profile.",
          "expected": "The original pre-registered telephone number remains unchanged."
        }
      ]
    },
    {
      "id": "TC-3",
      "title": "Setting phone number for a new representative triggers binding",
      "covers": [
        "KDH-009"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "A company account exists. A new company representative is being added or is updating their profile for the first time.",
      "test_inputs": "A valid telephone number for the new representative.",
      "assumptions": "The 'setting' of a pre-registered number for a new representative is treated as binding a new authenticator.",
      "steps": [
        {
          "no": 1,
          "action": "Provide a telephone number for the new company representative during the registration or profile setup.",
          "expected": "The system treats this as an authenticator binding event and sends a verification code to the provided number."
        },
        {
          "no": 2,
          "action": "Verify the code sent to the telephone number.",
          "expected": "The telephone number is successfully bound as the pre-registered number for the representative."
        }
      ]
    }
  ]
}

