      "assumptions": "The authoritative source returns a positive match for the provided attributes.",
      "steps": [
        {
          "no": 1,
          "action": "Initiate the proofing process for the company representative user at IAL2.",
          "expected": "The system prompts for core attributes including government identifier and company details."
        },
        {
          "no": 2,
          "action": "Submit the valid government identifier and core attributes that match the authoritative source.",
          "expected": "The system validates the attributes against the authoritative source and returns a success status."
        },
        {
          "no": 3,
          "action": "Check the user's assurance level status in the system.",
          "expected": "The user's identity is marked as verified at IAL2."
        }
      ]
    },
