      "test_inputs": "A digitally signed evidence document containing core attributes, signed by a trusted issuer.",
      "assumptions": "The issuer's public key is available in the system's trust store and the signature is cryptographically valid.",
      "steps": [
        {
          "no": 1,
          "action": "Initiate the proofing process for the company representative user at IAL2.",
          "expected": "The system accepts the upload or input of the digitally signed evidence document."
        },
        {
          "no": 2,
          "action": "Submit the digitally signed evidence document.",
          "expected": "The system validates the digital signature using the issuer's public key and extracts the core attributes."
        },
        {
          "no": 3,
          "action": "Check the user's assurance level status in the system.",
          "expected": "The user's identity is marked as verified at IAL2 based on the validated digital signature."
        }
      ]
    },
    {
      "id": "TC-03",
      "title": "IAL2 Proofing Failure Due to Mismatched Attributes in Authoritative Source",
      "covers": [
        "KDH-018"
      ],
      "type": "Hata",
      "priority": "Yüksek",
      "preconditions": "A test user account is created with IAL2 assurance level. The user is identified as a company representative. The authoritative source contains different core attributes than those submitted.",
      "test_inputs": "Valid government identifier but incorrect company registration number or other core attributes that do not match the authoritative source.",
      "assumptions": "The authoritative source returns a negative match for the provided attributes.",
      "steps": [
        {
          "no": 1,
          "action": "Initiate the proofing process for the company representative user at IAL2.",
          "expected": "The system prompts for core attributes."
        },
        {
          "no": 2,
          "action": "Submit core attributes that do not match the authoritative source.",
          "expected": "The system fails the validation and displays an error message indicating the mismatch."
        },
        {
          "no": 3,
          "action": "Check the user's assurance level status in the system.",
          "expected": "The user's identity is not verified at IAL2."
        }
      ]
    },
    {
      "id": "TC-04",
      "title": "IAL2 Proofing Failure Due to Invalid Digital Signature",
      "covers": [
        "KDH-018"
      ],
      "type": "Hata",
      "priority": "Yüksek",
      "preconditions": "A test user account is created with IAL2 assurance level. The user is identified as a company representative. A digitally signed evidence document is prepared with an invalid or tampered signature.",
      "test_inputs": "A digitally signed evidence document with an invalid signature or a signature from an untrusted issuer.",
      "assumptions": "The system detects the invalid signature or untrusted issuer.",
      "steps": [
        {
