        },
        {
          "no": 2,
          "action": "Submit the digitally signed evidence document with an invalid signature.",
          "expected": "The system fails the signature validation and displays an error message indicating the invalid signature."
        },
        {
          "no": 3,
          "action": "Check the user's assurance level status in the system.",
          "expected": "The user's identity is not verified at IAL2."
        }
      ]
    }
  ]
